import{_ as l,a0 as o,w as p,s as u,I as e,x as a,a1 as n,A as s,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"GitHub 是如何迁移 MySQL 集群的 | LCTT x X-CMD","titleTemplate":false,"description":"GitHub 是如何迁移 MySQL 集群的 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GitHub 是如何迁移 MySQL 集群的 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GitHub 是如何迁移 MySQL 集群的 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140904 Making MySQL Better at GitHub","title":"GitHub 是如何迁移 MySQL 集群的","tag":"201410","desc":""},"relativePath":"201410/20140904 Making MySQL Better at GitHub.md","filePath":"[post].md"}'),d={name:"201410/20140904 Making MySQL Better at GitHub.md"};function b(m,t,g,f,h,T){const i=o("Link");return p(),u("div",null,[t[23]||(t[23]=e("h1",{id:"github-是如何迁移-mysql-集群的",tabindex:"-1"},[a("GitHub 是如何迁移 MySQL 集群的 "),e("a",{class:"header-anchor",href:"#github-是如何迁移-mysql-集群的","aria-label":"Permalink to “GitHub 是如何迁移 MySQL 集群的”"},"​")],-1)),e("blockquote",null,[e("p",null,[t[1]||(t[1]=a("在 GitHub 我们总是说“如果网站响应速度不够快，我们就不应该让它上线运营”。我们之前在",-1)),n(i,{href:"https://github.com/blog/1756-optimizing-large-selector-sets"},{default:s(()=>[...t[0]||(t[0]=[a("前端的体验速度",-1)])]),_:1}),t[2]||(t[2]=a("这篇文章中介绍了一些提高网站响应速率的方法，但这只是故事的一部分。真正影响到 GitHub.com 性能的因素是 MySQL 数据库架构。让我们来瞧瞧我们的基础架构团队是如何无缝升级了 MySQL 架构吧，这事儿发生在去年8月份，成果就是大大提高了 GitHub 网站的速度。",-1))])]),t[24]||(t[24]=r('<h3 id="任务" tabindex="-1">任务 <a class="header-anchor" href="#任务" aria-label="Permalink to “任务”">​</a></h3><p>去年我们把 GitHub 上的大部分数据移到了新的数据中心，这个中心有世界顶级的硬件资源和网络平台。自从使用了 MySQL 作为我们的后端系统的基础，我们一直期望着一些改进来大大提高数据库性能，但是在数据中心使用全新的硬件来部署一套全新的集群环境并不是一件简单的工作，所以我们制定了一套计划和测试工作，以便数据能平滑过渡到新环境。</p><h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to “准备工作”">​</a></h3><p>像我们这种关于架构上的巨大改变，在执行的每一步都需要收集数据指标。新机器上安装好了基本的操作系统，接下来就是测试新配置下的各种性能。为了模拟真实的工作负载环境，我们使用 tcpdump 工具从旧的集群那里复制正在发生的 SELECT 请求，并在新集群上重新回放一遍。</p><p>MySQL 调优是个繁琐的细致活，像众所周知的 innodb_buffer_pool_size 这个参数往往能对 MySQL 性能产生巨大的影响。对于这类参数，我们必须考虑在内，所以我们列了一份参数清单，包括 innodb_thread_concurrency，innodb_io_capacity，和 innodb_buffer_pool_instances，还有其它的。</p><p>在每次测试中，我们都很小心地只改变一个参数，并且让一次测试至少运行12小时。我们会观察响应时间的变化曲线，每秒的响应次数，以及有可能会导致并发性降低的参数。我们使用 “SHOW ENGINE INNODB STATUS” 命令打印 InnoDB 性能信息，特别观察了 “SEMAPHORES” 一节的内容，它为我们提供了工作负载的状态信息。</p><p>当我们在设置参数后对运行结果感到满意，然后就开始将我们最大的数据表格之一迁移到一套独立的集群上，这个步骤作为整个迁移过程的早期测试，以保证我们的核心集群有更多的缓存池空间，并且为故障切换和存储功能提供更强的灵活性。这步初始迁移方案也引入了一个有趣的挑战：我们必须维持多条客户连接，并且要将这些连接指向到正确的集群上。</p><p>除了硬件性能的提升，还需要补充一点，我们同时也对处理进程和拓扑结构进行了改进：我们添加了延时拷贝技术，更快、更高频地备份数据，以及更多的读拷贝空间。这些功能已经准备上线。</p><h3 id="列出任务清单-三思后行" tabindex="-1">列出任务清单，三思后行 <a class="header-anchor" href="#列出任务清单-三思后行" aria-label="Permalink to “列出任务清单，三思后行”">​</a></h3>',9)),e("p",null,[t[4]||(t[4]=a("每天有上百万用户的使用 GitHub.com，我们不可能有机会等没有人用了才进行实际数据切换。我们有一个详细的",-1)),n(i,{href:"https://help.github.com/articles/writing-on-github#task-lists"},{default:s(()=>[...t[3]||(t[3]=[a("任务清单",-1)])]),_:1}),t[5]||(t[5]=a("来执行迁移：",-1))]),t[25]||(t[25]=e("p",null,[e("img",{src:"https://cloud.githubusercontent.com/assets/1155781/4116929/13fc6f50-328b-11e4-837b-922aad3055a8.png",alt:""})],-1)),e("p",null,[t[7]||(t[7]=a("我们还规划了一个维护期，并且",-1)),n(i,{href:"https://github.com/blog/1603-site-maintenance-august-31st-2013"},{default:s(()=>[...t[6]||(t[6]=[a("在我们的博客中通知了大家",-1)])]),_:1}),t[8]||(t[8]=a("，让用户注意到这件事情。",-1))]),t[26]||(t[26]=r('<h3 id="迁移时间到" tabindex="-1">迁移时间到 <a class="header-anchor" href="#迁移时间到" aria-label="Permalink to “迁移时间到”">​</a></h3><p>太平洋时间星期六上午5点，我们的迁移团队上线集合对话，同时数据迁移正式开始：</p><p><img src="https://cloud.githubusercontent.com/assets/1155781/4060850/39f52cd4-2df3-11e4-9aca-1f54a4870d24.png" alt=""></p><p>我们将 GitHub 网站设置为维护模式，并在 Twitter 上发表声明，然后开始按上述任务清单的步骤开始工作：</p><p><img src="https://cloud.githubusercontent.com/assets/1155781/4060864/54ff6bac-2df3-11e4-95da-b059c0ec668f.png" alt=""></p><p><strong>13 分钟</strong>后，我们确保新的集群能正常工作：</p><p><img src="https://cloud.githubusercontent.com/assets/1155781/4060870/6a4c0060-2df3-11e4-8dab-654562fe628d.png" alt=""></p><p>然后我们让 GitHub.com 脱离维护模式，并且让全世界的用户都知道我们的最新状态：</p><p><img src="https://cloud.githubusercontent.com/assets/1155781/4060878/79b9884c-2df3-11e4-98ed-d11818c8915a.png" alt=""></p><p>大量前期的测试工作与准备工作，让我们将维护期缩到最短。</p><h3 id="检验最终的成果" tabindex="-1">检验最终的成果 <a class="header-anchor" href="#检验最终的成果" aria-label="Permalink to “检验最终的成果”">​</a></h3><p>在接下来的几周时间里，我们密切监视着 GitHub.com 的性能和响应时间。我们发现迁移后网站的平均加载时间减少一半，并且在99%的时间里，能减少<em>三分之二</em>：</p><p><img src="https://cloud.githubusercontent.com/assets/1155781/4060886/9106e54e-2df3-11e4-8fda-a4c64c229ba1.png" alt=""></p><h3 id="我们学到了什么" tabindex="-1">我们学到了什么 <a class="header-anchor" href="#我们学到了什么" aria-label="Permalink to “我们学到了什么”">​</a></h3><h4 id="功能划分" tabindex="-1">功能划分 <a class="header-anchor" href="#功能划分" aria-label="Permalink to “功能划分”">​</a></h4><p>在迁移过程中，我们采用了一个比较好的方法是：将大的数据表（主要记录了一些历史数据）先迁移过去，空出旧集群的磁盘空间和缓存池空间。这一步给我们留下了更多的资源用于“热”数据，将一些连接请求分离到多套集群里面。这步为我们之后的胜利奠定了基础，我们以后还会使用这种模式来进行迁移工作。</p><h4 id="测试测试测试" tabindex="-1">测试测试测试 <a class="header-anchor" href="#测试测试测试" aria-label="Permalink to “测试测试测试”">​</a></h4><p>为你的应用做验收测试和回归测试，越多越好，多多益善，不要嫌多。从老集群复制数据到新集群的过程中，如果进行验收测试和响应状态测试，得到的数据是不准的，如果数据不理想，这是正常的，不要惊讶，不要试图拿这些数据去分析原因。</p><h4 id="合作的力量" tabindex="-1">合作的力量 <a class="header-anchor" href="#合作的力量" aria-label="Permalink to “合作的力量”">​</a></h4><p>对基础架构进行大的改变，通常需要涉及到很多人，我们要像一个团队一样为共同的目标而合作。我们的团队成员来自全球各地。</p><p>团队成员地图：</p>',21)),e("p",null,[n(i,{href:"https://render.githubusercontent.com/view/geojson?url=https://gist.githubusercontent.com/anonymous/5fa29a7ccbd0101630da/raw/map.geojson"},{default:s(()=>[...t[9]||(t[9]=[a("https://render.githubusercontent.com/view/geojson?url=https://gist.githubusercontent.com/anonymous/5fa29a7ccbd0101630da/raw/map.geojson",-1)])]),_:1})]),t[27]||(t[27]=e("p",null,"本次合作新创了一种工作流程：我们提交更改（pull request），获取实时反馈，查看修改了错误的 commit —— 全程没有电话交流或面对面的会议。当所有东西都可以通过 URL 提供信息，不同区域的人群之间的交流和反馈会变得非常简单。",-1)),t[28]||(t[28]=e("h3",{id:"一年后",tabindex:"-1"},[a("一年后…… "),e("a",{class:"header-anchor",href:"#一年后","aria-label":"Permalink to “一年后……”"},"​")],-1)),t[29]||(t[29]=e("p",null,"整整一年时间过去了，我们很高兴地宣布这次数据迁移是很成功的 —— MySQL 性能和可靠性一直处于我们期望的状态。另外，新的集群还能让我们进一步去升级，提供更好的可靠性和响应时间。我将继续记录这些优化过程。",-1)),t[30]||(t[30]=e("hr",null,null,-1)),e("p",null,[t[11]||(t[11]=a("via: ",-1)),n(i,{href:"https://github.com/blog/1880-making-mysql-better-at-github"},{default:s(()=>[...t[10]||(t[10]=[a("https://github.com/blog/1880-making-mysql-better-at-github",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=a("作者：",-1)),n(i,{href:"https://github.com/samlambert"},{default:s(()=>[...t[12]||(t[12]=[a("samlambert",-1)])]),_:1}),t[16]||(t[16]=a(" 译者：",-1)),n(i,{href:"https://github.com/bazz2"},{default:s(()=>[...t[13]||(t[13]=[a("bazz2",-1)])]),_:1}),t[17]||(t[17]=a(" 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[14]||(t[14]=[a("wxy",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[18]||(t[18]=[a("LCTT",-1)])]),_:1}),t[21]||(t[21]=a(" 原创翻译，",-1)),n(i,{href:"http://linux.cn/"},{default:s(()=>[...t[19]||(t[19]=[a("Linux中国",-1)])]),_:1}),t[22]||(t[22]=a(" 荣誉推出",-1))])])}const M=l(d,[["render",b]]);export{y as __pageData,M as default};
